mapper.select:
SELECT CASE WHEN c.tool_source = 'SKILL_LOCAL' THEN 'SKILL_LOCAL' WHEN c.mcp_server_id IS NULL AND c.tool_source_key = 'workbench' THEN 'WORKBENCH_MCP' ELSE 'EXTERNAL_MCP' END AS source, COUNT(*) AS calls FROM agent_execution_tool_call c JOIN agent_execution e ON e.id = c.execution_id WHERE e.space_id = #{query.spaceId} AND c.started_at >= #{query.startAt} AND c.started_at < #{query.endAt}
AND e.agent_id = #{query.agentId}
AND EXISTS ( SELECT 1 FROM agent_execution_model_call m WHERE m.execution_id = e.id AND m.model_id = #{query.modelId} )
AND e.status = #{query.executionStatus}
GROUP BY CASE WHEN c.tool_source = 'SKILL_LOCAL' THEN 'SKILL_LOCAL' WHEN c.mcp_server_id IS NULL AND c.tool_source_key = 'workbench' THEN 'WORKBENCH_MCP' ELSE 'EXTERNAL_MCP' END
